/*
 * A354499  Number of consecutive primes generated by adding 2n to the odd
 *          squares (A016754).
 * https://oeis.org/A354499
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of consecutive primes generated by (2x-1)^2 + 2n *
 *            for x = 1,2,3,... until the first composite value. * a(1)=2,
 *            a(2)=4, a(3)=1,
 * Range:     u8 n <= 28, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/is_prime_big.h"

seq_t a(idx_t n)
{
    /* Offset: a(1) is the first term.  For n <= 0 we return 0. */
    if (n == 0) return 0;

    seq_t count = 0;
    seq_t two_n = (seq_t)2 * (seq_t)n;          /* 2*n */

    for (idx_t x = 1;; ++x)
    {
        seq_t odd  = (seq_t)2 * (seq_t)x - 1;   /* 2x-1 */
        seq_t val  = odd * odd + two_n;        /* (2x-1)^2 + 2n */

        if (!is_prime_big(val))
            break;                            /* first composite found */

        count++;                              /* prime succeeded */
    }

    return count;
}
